// smoke.spec.js — MP3 Cutter and Audio Trimmer: the core cut-and-save flow on bundled fictional fixtures.
// tests/fixtures/sample-song.mp3 ("Sample Song" by the fictional "Demo Band") is generated by tests/tools/make-sample-song.js:
// 20 s stereo 44.1 kHz, tones at 0–6 s, 8–13 s and 14.5–20 s with quiet gaps.
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);
const SONG = fixture('sample-song.mp3');

function watch(page) {
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  return errors;
}

// Same formula as formatBytes in site.js.
function formatBytes(n) {
  const units = ['B', 'KB', 'MB', 'GB'];
  let i = 0;
  while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
  return `${n < 10 && i > 0 ? n.toFixed(1) : Math.round(n)} ${units[i]}`;
}

async function dropFile(page, file, name, type) {
  const b64 = fs.readFileSync(file).toString('base64');
  await page.evaluate(({ b64, name, type }) => {
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    const dt = new DataTransfer();
    dt.items.add(new File([bytes], name, { type }));
    document.getElementById('dropzone').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
  }, { b64, name, type });
}

async function openSong(page) {
  await page.setInputFiles('#file-input', SONG);
  await expect(page.locator('#editor')).toBeVisible();
  await expect(page.locator('#handle-end')).toHaveAttribute('aria-valuenow', /^(19\.\d|20\.\d)$/);
}

// Decodes downloaded audio inside the page and reports duration, channels, rate and RMS of the first/last 0.25 s.
async function analyse(page, bytes) {
  return page.evaluate(async (b64) => {
    const data = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    const buf = await new OfflineAudioContext(1, 1, 44100).decodeAudioData(data.buffer);
    const ch = buf.getChannelData(0);
    const rms = (from, to) => { let s = 0; for (let i = from; i < to; i++) s += ch[i] * ch[i]; return Math.sqrt(s / Math.max(1, to - from)); };
    const q = Math.round(buf.sampleRate * 0.25);
    // skip the encoder's start-up delay (a few ms) when measuring the head
    const head = Math.round(buf.sampleRate * 0.03);
    return { duration: buf.duration, channels: buf.numberOfChannels, rate: buf.sampleRate, headRms: rms(head, head + q), tailRms: rms(ch.length - q - head, ch.length - head) };
  }, bytes.toString('base64'));
}

async function setTimes(page, start, end) {
  await page.fill('#end', end);
  await page.press('#end', 'Enter');
  await page.fill('#start', start);
  await page.press('#start', 'Enter');
}

async function cutAndDownload(page) {
  const [download] = await Promise.all([page.waitForEvent('download'), page.click('#cut')]);
  const bytes = fs.readFileSync(await download.path());
  return { download, bytes };
}

test.describe('MP3 Cutter and Audio Trimmer', () => {
  test('empty state explains the supported formats', async ({ page }) => {
    await page.goto('./');
    await expect(page.locator('#dropzone-hint')).toContainText(/MP3, WAV, M4A, OGG or FLAC/);
    await expect(page.locator('#editor')).toBeHidden();
  });

  test('dropping sample-song.mp3 draws a waveform with two draggable trim handles', async ({ page }) => {
    const errors = watch(page);
    await page.goto('./');
    await dropFile(page, SONG, 'sample-song.mp3', 'audio/mpeg');
    await expect(page.locator('#editor')).toBeVisible();
    await expect(page.locator('#file-name')).toHaveText('sample-song.mp3');
    await expect(page.locator('#file-meta')).toContainText('00:20.0');
    await expect(page.locator('#file-meta')).toContainText('stereo');
    await expect(page.locator('#file-meta')).toContainText('44.1 kHz');

    // The canvas has real drawn pixels, and loud sections are taller than the quiet gap at 7 s.
    const ink = await page.evaluate(() => {
      const c = document.getElementById('wave-canvas');
      const g = c.getContext('2d');
      const col = (t) => { const x = Math.floor(c.width * t / 20); const d = g.getImageData(x, 0, 1, c.height).data; let n = 0; for (let i = 3; i < d.length; i += 4) if (d[i] > 0) n++; return n; };
      return { w: c.width, h: c.height, loud: col(3), gap: col(7) };
    });
    expect(ink.w).toBeGreaterThan(100);
    expect(ink.loud).toBeGreaterThan(ink.h * 0.5);
    expect(ink.gap).toBeLessThan(ink.h * 0.1);

    const handles = page.locator('#wave [role="slider"]');
    await expect(handles).toHaveCount(2);
    await expect(page.locator('#handle-start')).toHaveAttribute('aria-valuenow', '0.0');

    // Drag the start handle to about a quarter of the way (5 s).
    const wave = await page.locator('#wave').boundingBox();
    const hs = await page.locator('#handle-start').boundingBox();
    await page.mouse.move(hs.x + hs.width / 2, hs.y + hs.height / 2);
    await page.mouse.down();
    await page.mouse.move(wave.x + wave.width * 0.25, hs.y + hs.height / 2, { steps: 8 });
    await page.mouse.up();
    const start = Number(await page.locator('#handle-start').getAttribute('aria-valuenow'));
    expect(start).toBeGreaterThan(4.6);
    expect(start).toBeLessThan(5.4);
    await expect(page.locator('#start')).toHaveValue(/^00:0[45]\.\d$/);

    // Drag the end handle left past the start: it is clamped just after the start.
    const he = await page.locator('#handle-end').boundingBox();
    await page.mouse.move(he.x + he.width / 2, he.y + he.height / 2);
    await page.mouse.down();
    await page.mouse.move(wave.x + 2, he.y + he.height / 2, { steps: 8 });
    await page.mouse.up();
    const end = Number(await page.locator('#handle-end').getAttribute('aria-valuenow'));
    expect(end).toBeGreaterThan(start);
    expect(end - start).toBeLessThan(0.25);

    // Keyboard: arrows nudge the active handle 0.1 s, shift 1 s.
    await page.locator('#handle-end').focus();
    await page.keyboard.press('Shift+ArrowRight');
    await page.keyboard.press('ArrowRight');
    const nudged = Number(await page.locator('#handle-end').getAttribute('aria-valuenow'));
    expect(nudged - end).toBeCloseTo(1.1, 1);

    // Space toggles the preview.
    await page.keyboard.press('Space');
    await expect(page.locator('#stop')).toBeEnabled();
    await page.keyboard.press('Space');
    await expect(page.locator('#stop')).toBeDisabled();
    expect(errors).toEqual([]);
  });

  test('start 00:05.0 and end 00:15.0, Cut downloads an MP3 about 10 seconds long', async ({ page }) => {
    const errors = watch(page);
    await page.goto('./');
    await openSong(page);
    await setTimes(page, '00:05.0', '00:15.0');
    await expect(page.locator('#length')).toHaveText('00:10.0');
    const { download, bytes } = await cutAndDownload(page);
    expect(download.suggestedFilename()).toBe('sample-song-cut.mp3');
    // 10 s at 128 kbps is about 160 KB
    expect(bytes.length).toBeGreaterThan(140_000);
    expect(bytes.length).toBeLessThan(180_000);
    const isMp3 = bytes[0] === 0xff && (bytes[1] & 0xe0) === 0xe0;
    expect(isMp3 || bytes.slice(0, 3).toString() === 'ID3').toBeTruthy();
    const a = await analyse(page, bytes);
    expect(a.duration).toBeGreaterThan(9.9);
    expect(a.duration).toBeLessThan(10.2);
    expect(a.channels).toBe(2);
    expect(errors).toEqual([]);
  });

  test('the result shows the new duration and file size, with a named download link', async ({ page }) => {
    await page.goto('./');
    await openSong(page);
    await setTimes(page, '2', '9.5');
    await page.selectOption('#bitrate', '192');
    const { bytes } = await cutAndDownload(page);
    const result = page.locator('#results .result');
    await expect(result).toHaveCount(1);
    await expect(result).toContainText('Duration 00:07.5');
    await expect(result).toContainText(formatBytes(bytes.length));
    await expect(result).toContainText('MP3 192 kbps');
    const link = page.locator('#download');
    await expect(link).toHaveAttribute('download', 'sample-song-cut.mp3');
    await expect(link).toHaveText('Download sample-song-cut.mp3');
    // the link offers the same file again
    const [again] = await Promise.all([page.waitForEvent('download'), link.click()]);
    expect(fs.readFileSync(await again.path()).length).toBe(bytes.length);
  });

  test('fade in and fade out toggles change the exported audio without errors', async ({ page }) => {
    const errors = watch(page);
    await page.goto('./');
    await openSong(page);
    await setTimes(page, '00:01.0', '00:05.0'); // all inside the loud first tone
    const plain = await analyse(page, (await cutAndDownload(page)).bytes);

    await page.check('#fade-in-on');
    await page.check('#fade-out-on');
    await page.fill('#fade-in', '1');
    await page.fill('#fade-out', '1');
    const faded = await analyse(page, (await cutAndDownload(page)).bytes);
    await expect(page.locator('#results .result')).toContainText('fade in 1 s, fade out 1 s');

    expect(plain.headRms).toBeGreaterThan(0.3);
    expect(plain.tailRms).toBeGreaterThan(0.3);
    expect(faded.headRms).toBeLessThan(plain.headRms * 0.3);
    expect(faded.tailRms).toBeLessThan(plain.tailRms * 0.3);
    expect(Math.abs(faded.duration - plain.duration)).toBeLessThan(0.05);

    // Turning them off again restores the plain export.
    await page.uncheck('#fade-in-on');
    await page.uncheck('#fade-out-on');
    const off = await analyse(page, (await cutAndDownload(page)).bytes);
    expect(off.headRms).toBeGreaterThan(plain.headRms * 0.9);
    await expect(page.locator('.alert--error')).toHaveCount(0);
    expect(errors).toEqual([]);
  });

  test('WAV export keeps the sample rate and channels, delete mode keeps the rest', async ({ page }) => {
    await page.goto('./');
    await openSong(page);
    await setTimes(page, '00:05.0', '00:15.0');
    await page.selectOption('#mode', 'delete');
    await page.selectOption('#format', 'wav');
    await expect(page.locator('#bitrate')).toBeDisabled();
    const { download, bytes } = await cutAndDownload(page);
    expect(download.suggestedFilename()).toBe('sample-song-cut.wav');
    expect(bytes.slice(0, 4).toString()).toBe('RIFF');
    expect(bytes.slice(8, 12).toString()).toBe('WAVE');
    expect(bytes.readUInt16LE(22)).toBe(2);
    expect(bytes.readUInt32LE(24)).toBe(44100);
    expect(bytes.readUInt16LE(34)).toBe(16);
    const seconds = bytes.readUInt32LE(40) / (44100 * 2 * 2);
    expect(seconds).toBeGreaterThan(9.95);
    expect(seconds).toBeLessThan(10.2);
    await expect(page.locator('#results .result')).toContainText('WAV 16-bit');
  });

  test('Unicode file names are kept in the download name', async ({ page }) => {
    await page.goto('./');
    await page.setInputFiles('#file-input', { name: 'Démo Bänd – Canción 夜.mp3', mimeType: 'audio/mpeg', buffer: fs.readFileSync(SONG) });
    await expect(page.locator('#editor')).toBeVisible();
    await setTimes(page, '1', '3');
    const { download } = await cutAndDownload(page);
    expect(download.suggestedFilename()).toBe('Démo Bänd – Canción 夜-cut.mp3');
  });

  test('a non audio file shows a clear error message and no crash', async ({ page }) => {
    const errors = [];
    page.on('pageerror', (e) => errors.push(String(e)));
    await page.goto('./');
    await page.setInputFiles('#file-input', fixture('sample.txt'));
    const alert = page.locator('#results .alert.alert--error');
    await expect(alert).toBeVisible();
    await expect(alert).toContainText('"sample.txt" is not an audio file');
    await expect(page.locator('#editor')).toBeHidden();

    // A file that claims to be MP3 but is not decodable.
    await page.setInputFiles('#file-input', { name: 'broken.mp3', mimeType: 'audio/mpeg', buffer: Buffer.from('this is not really audio '.repeat(200)) });
    await expect(alert).toContainText('Could not read "broken.mp3" as audio');
    await expect(page.locator('#editor')).toBeHidden();

    // Mixed with a valid file: the wrong one is named, the audio still opens.
    await dropFile(page, fixture('sample.pdf'), 'notes.pdf', 'application/pdf');
    await expect(alert).toContainText('"notes.pdf" is not an audio file');
    await page.evaluate(async () => {
      const bytes = await (await fetch('./tests/fixtures/sample-song.mp3')).arrayBuffer();
      const dt = new DataTransfer();
      dt.items.add(new File(['plain text'], 'readme.txt', { type: 'text/plain' }));
      dt.items.add(new File([bytes], 'sample-song.mp3', { type: 'audio/mpeg' }));
      document.getElementById('dropzone').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
    });
    await expect(page.locator('#editor')).toBeVisible();
    await expect(alert).toContainText('"readme.txt" is not an audio file');
    await expect(page.locator('#file-name')).toHaveText('sample-song.mp3');
    expect(errors).toEqual([]);
  });

  test('the layout works at 390px wide', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await expect(page.locator('#dropzone')).toBeInViewport();
    await openSong(page);
    await setTimes(page, '00:05.0', '00:15.0');
    await cutAndDownload(page);
    await expect(page.locator('#results .result')).toBeVisible();
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    for (const sel of ['#wave', '#handle-start', '#handle-end', '#cut', '#play', '#download', '#mode', '#fade-out']) {
      const box = await page.locator(sel).boundingBox();
      expect(box.x, `${sel} starts on screen`).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width, `${sel} ends on screen`).toBeLessThanOrEqual(390);
    }
    // Handles at the extreme ends still fit on screen.
    await setTimes(page, '0', '20');
    const end = await page.locator('#handle-end').boundingBox();
    expect(end.x + end.width).toBeLessThanOrEqual(390);
  });

  test('__demo shows a finished cut of Sample Song by Demo Band', async ({ page }) => {
    const errors = watch(page);
    await page.goto('./');
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#file-name')).toHaveText('Demo Band - Sample Song.mp3');
    await expect(page.locator('#results .result')).toContainText('Duration 00:09.5');
    await expect(page.locator('#download')).toHaveText('Download Demo Band - Sample Song-cut.mp3');
    expect(errors).toEqual([]);
  });
});
